changeSet.sql:
ALTER TABLE tenant_redaction_catalog ADD CONSTRAINT ck_tenant_redaction_catalog_style
    CHECK (style IN ('REMOVE_FULLY', 'KEEP_LAST_FOUR'));
-- Locked items are never shown in part, whatever writes the row.
ALTER TABLE tenant_redaction_catalog ADD CONSTRAINT ck_tenant_redaction_catalog_locked
    CHECK (kind_key NOT IN ('CREDIT_CARD_NUMBER', 'CVV', 'PIN') OR style = 'REMOVE_FULLY');

rollback.sql:
ALTER TABLE tenant_redaction_policies
    ADD COLUMN ssn_enabled BOOLEAN NOT NULL DEFAULT true,
    ADD COLUMN date_of_birth_enabled BOOLEAN NOT NULL DEFAULT true,
    ADD COLUMN credit_card_number_enabled BOOLEAN NOT NULL DEFAULT true,
    ADD COLUMN credit_score_enabled BOOLEAN NOT NULL DEFAULT true;
UPDATE tenant_redaction_policies p SET
    ssn_enabled = EXISTS (SELECT 1 FROM tenant_redaction_catalog c WHERE c.tenant_id = p.tenant_id
        AND c.kind_key = 'SSN' AND c.enabled),
    date_of_birth_enabled = EXISTS (SELECT 1 FROM tenant_redaction_catalog c WHERE c.tenant_id = p.tenant_id
        AND c.kind_key = 'DATE_OF_BIRTH' AND c.enabled),
    credit_card_number_enabled = EXISTS (SELECT 1 FROM tenant_redaction_catalog c WHERE c.tenant_id = p.tenant_id
        AND c.kind_key = 'CREDIT_CARD_NUMBER' AND c.enabled),
    credit_score_enabled = EXISTS (SELECT 1 FROM tenant_redaction_catalog c WHERE c.tenant_id = p.tenant_id
        AND c.kind_key = 'CREDIT_SCORE' AND c.enabled);
CREATE TABLE tenant_redaction_kinds (
    tenant_id UUID NOT NULL CONSTRAINT fk_tenant_redaction_kinds_tenant REFERENCES tenants (id),
    kind_key VARCHAR(64) NOT NULL,
    enabled BOOLEAN NOT NULL DEFAULT false,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_tenant_redaction_kinds PRIMARY KEY (tenant_id, kind_key));
INSERT INTO tenant_redaction_kinds (tenant_id, kind_key, enabled, updated_at)
SELECT tenant_id, kind_key, enabled, updated_at FROM tenant_redaction_catalog
 WHERE kind_key IN ('BANK_ROUTING_NUMBER', 'BANK_ACCOUNT_NUMBER', 'ITIN', 'EIN',
                    'DRIVERS_LICENSE_NUMBER', 'PASSPORT_NUMBER');
-- The version before can't read the new kinds' names.
UPDATE findings SET entity_type = 'CUSTOM' WHERE entity_type IN ('CVV', 'PIN');
ALTER TABLE findings DROP COLUMN redaction_style;
ALTER TABLE tenant_redaction_policies DROP COLUMN locked_items_on;
DROP TABLE tenant_regulation_packs;
DROP TABLE tenant_redaction_catalog;
